(function(){const STEPS="Open Messenger > Menu > Settings > Username, then enter m.me/your-username";function toggle(btn){const holder=btn.parentNode;let line=holder.querySelector(".fbh-steps");if(!line){line=document.createElement("span");line.className="fbh-steps";line.id=(holder.id||"messenger-help")+"-steps";line.textContent=STEPS;line.hidden=true;holder.appendChild(line);btn.setAttribute("aria-controls",line.id)}line.hidden=!line.hidden;btn.setAttribute("aria-expanded",line.hidden?"false":"true")}document.addEventListener("click",e=>{const btn=e.target.closest("[data-fb-help]");if(!btn)return;e.preventDefault();toggle(btn)})})();